template <class T> T* IVS_NEW(T*& m, unsigned long ulMuili = 0)
{
    m = NULL;
    if (ulMuili == 0) {
        try {
            m = new (T);
        } catch (...) {
            if (NULL != m) {
                delete m;
            }
            m = NULL;
        }
    } else {
        try {
            m = new (T[ulMuili]);
        } catch (...) {
            if (NULL != m) {
                delete[] m;
            }
            m = NULL;
        }
    }

    return m;
};

template <class T> void IVS_DELETE(T*& m, unsigned long ulMuili = 0)
{
    if (NULL == m) {
        return;
    }

    try {
        if (0 == ulMuili) {
            delete m;
        } else {
            delete[] m;
        }
    } catch (...) {
    }

    m = NULL;
};





