{
    UserDefineMemNode *node = (UserDefineMemNode *)malloc(sizeof(UserDefineMemNode));
    if (node == NULL) {
        return NULL;
    }
    node->type = type;

    size_t size = USER_DEFINE_MEM_DEFAULT_VALUE_SIZE;
    if (type == USER_DEFINE_MEM1) {
        size = USER_DEFINE_MEM1_VALUE_SIZE;
    } else if (type == USER_DEFINE_MEM2) {
        size = USER_DEFINE_MEM2_VALUE_SIZE;
    }

    node->value = malloc(size);
    if (node->value == NULL) {
        free(node);
        node = NULL;
    }
    return node;
}

void UserDefineMemFree(UserDefineMemNode *node)
{
    if (node != NULL) {
        if (node->value != NULL) {
            free(node->value);
            node->value = NULL;
        }
        free(node);
    }
}

