void delipaddrnodeTGTcase(in6addr_s *ipaddr, poolv6core *poolcore)
{

    Poolv6IpNode *ipAddrNode = GetIpAddrNode(ipAddr, poolCore);
    if (ipAddrNode == nullptr) {
        return;
    }
    Poolv6ClientNode *clientNode = ipAddrNode->clientNode;
    if ((clientNode != nullptr) && (clientNode->ipCnt > 0)) {
        clientNode->ipCnt--;
    }
    VOS_ListRemove(&ipAddrNode->ipListNode);
    ipAddrNode->clientNode = nullptr;
    VOS_AVL_DELETE(poolCore->ipv6Tree, ipAddrNode->allocIpAvlNode);


    IN6ADDR_S tempIpAddr;
    (void)memcpy_s(&tempIpAddr, sizeof(IN6ADDR_S), ipAddr, sizeof(IN6ADDR_S));


    (void)IAS_MemFree(425, ipAddrNode);
    ipAddrNode = nullptr;


    NotifyBakIpUserDel(poolCore, &tempIpAddr);  
    return;
}

