VOS_VOID abc_sendrcssrspTGT(abcsipflowvar *pflowvar)
{
    VOS_UINT32 ulBcId = VOS_NULL_DWORD;
    WarningHeaderInfo *pWarningHdrInfo  = VOS_NULL_PTR;

    PUB_CONDITION_VOID(pFlowVar == VOS_NULL_PTR);

    ulBcId = pFlowVar->ulBcId;

    if (SIP_MSG_INVITE_OXX_RSP == pFlowVar->usCurSipMsgType) {

        pWarningHdrInfo = VOS_MemAlloc(PID_TEST, DYNAMIC_DOPRA_MEM_PT, sizeof(WarningHeaderInfo));
        PUB_CONDITION_VOID(pWarningHdrInfo == VOS_NULL_PTR);

        if (EOK != memset_s(pWarningHdrInfo,  sizeof(WarningHeaderInfo), VOS_NULL, sizeof(WarningHeaderInfo))) {

            VOS_Free(pWarningHdrInfo); 
            return;
        }

        if (VOS_FALSE == ABC_GetWarningTextFromSipInfo(pWarningHdrInfo, pFlowVar->sipInfo)) {
            VOS_Free(pWarningHdrInfo); 
            ABC_SendRcssRspMsg(pFlowVar, ABC_SC_INNER_ERR);
            return;
        }

        if (RCSS_SUCCESS_LEN == VOS_StrNLen((VOS_CHAR *)pWarningHdrInfo->szRelDescription, MAX_WARNING_DESCRIPTION_LEN)
            && VOS_StrCmp((VOS_CHAR *)RCSS_SUCCESS, (VOS_CHAR *)pWarningHdrInfo->szRelDescription) == 0) {
            ABC_SendRcssRspMsg(pFlowVar, ABC_SC_SUCCESS);
        } else {
            if (VOS_TRUE == SP_IS_USE_NSOPERATE_TID_ON_RCSS) {
                ABC_SendRcssRspMsg(pFlowVar, ABC_SC_REALEASE);
            } else {
                ABC_SendRcssRspMsg(pFlowVar, ABC_SC_INNER_ERR);
            }
        }

        VOS_Free(pWarningHdrInfo); 
        return;
    }
    return;
}

