int OSFusionService::case3(const std::string &packagePath, uint64_t offset, uint32_t readSize,
    std::vector<char> &packagePart, std::string &checksum)
{
    if (m_status != ServiceStatus::RUNNING) {
        return -1;
    }

    if (readSize == 0) {
        return -1;
    }
    std::ifstream ifs(packagePath.c_str(), std::ios::binary);
    if (!ifs) {
        return -1;
    }

    ifs.seekg(offset);
    packagePart.resize(readSize);  

    uint32_t actualSize = 0;
    while (actualSize < readSize) {
        auto currentSize = ifs.readsome(packagePart.data() + actualSize, readSize - actualSize);
        if (currentSize <= 0) {
            break;
        }
        actualSize += currentSize;
    }
    checksum = std::to_string(actualSize);
    return static_cast<int>(actualSize);
}

