@RestController
public class CompiledScriptEvalInjection {
    private static final Logger LOGGER = LoggerFactory.getLogger(CompiledScriptEvalInjection.class);

    private static final String LETTER_DIGIT_REGEX = "^[a-z0-9A-Z]+$";

    private static final String[] SCRIPT_ARRAY = {"print('hello $param')", "print('age is $param')"};






    @GetMapping(path = "/CompiledScriptEvalInjection/TGT001")
    public void TGT001(int index, String param) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");
        try (StringWriter writer = new StringWriter()) {

            String script = SCRIPT_ARRAY[index];


            if (!param.matches(LETTER_DIGIT_REGEX)) {
                LOGGER.error("param is illegal");
                return;
            }
            VelocityEngine velocityEngine = new VelocityEngine();
            VelocityContext context = new VelocityContext();
            context.put("param", param);
            velocityEngine.evaluate(context, writer, "", script);


            CompiledScript compile = ((Compilable) engine).compile(writer.toString()); 
            compile.eval(); 
        } catch (ScriptException | IOException exception) {
            LOGGER.error("Some errors happened when executing the script");
        }
    }
}

