#define MAX_ARRAY_SIZE 4
#define BITS_PER_ELEMENT 32
typedef unsigned int uint32_t;

typedef struct {
    uint32_t array[MAX_ARRAY_SIZE];
} ArrayData;

ArrayData g_arrayData = {0};

int IsBitSet(uint32_t *bmp, uint32_t bitId)
{
    return (bmp[bitId / BITS_PER_ELEMENT] & (1 << (bitId % BITS_PER_ELEMENT))) != 0;
}

void ClearBit(uint32_t *bmp, uint32_t bitId)
{
    bmp[bitId / BITS_PER_ELEMENT] &= ~(1 << (bitId % BITS_PER_ELEMENT));
}

void TGTcase(uint32_t index)
{
    uint32_t *array = g_arrayData.array;

    for (uint32_t i = 0; i < MAX_ARRAY_SIZE; i++) {
        if (IsBitSet(&(array[i - 1]), index)) {  
            ClearBit(&(array[i - 1]), index);    
        }
    }
}

