#include <stdio.h>
#include <stdlib.h>
#include <string.h>



typedef struct NodeKey {
    int key1;
    int key2;
} NodeKey;


typedef struct Node {
    NodeKey key;
    struct Node *next;
} Node;


Node *CreateNode(NodeKey *key)
{
    Node *newNode = (Node *)malloc(sizeof(Node));
    newNode->key = *key;
    newNode->next = NULL;
    return newNode;
}


void Insert(Node **head, NodeKey *key)
{
    Node *newNode = CreateNode(key);
    newNode->next = *head;
    *head = newNode;
}


void Delete(Node **head, NodeKey *key)
{
    Node *temp = *head;
    Node *prev = NULL;


    while (temp != NULL && memcmp(&temp->key, key, sizeof(NodeKey)) != 0) {
        prev = temp;
        temp = temp->next;
    }


    if (temp == NULL) {
        printf("Node with key %d,%d not found\n", key->key1, key->key2);
        return;
    }


    if (prev == NULL) {
        *head = temp->next;
    } else {
        prev->next = temp->next;
    }

    free(temp);
}


void PrintList(Node *head)
{
    Node *temp = head;
    while (temp != NULL) {
        printf("%d,%d -> ", temp->key.key1, temp->key.key2);
        temp = temp->next;
    }
    printf("NULL\n");
}

int TGTcase()
{
    Node *head = NULL;
    NodeKey addkey = {0};
    NodeKey delKey = {0};


    addkey.key1 = 1;
    Insert(&head, &addkey);  

    printf("链表内容: ");
    PrintList(head);


    delKey.key1 = 1;
    Delete(&head, &delKey);  

    printf("删除未初始化key后的链表内容: ");
    PrintList(head);
}
